mapper.select:
SELECT 
FROM room r
WHERE r.room_id = #{roomId}

SELECT room_id
FROM user_pair_room
WHERE user_min = #{userMin} AND user_max = #{userMax}

SELECT last_seq
FROM room
WHERE room_id = #{roomId}

SELECT rm.room_id AS roomId, rm.user_id AS userId
FROM room_member rm
WHERE rm.room_id IN
#{roomId}
  AND rm.user_id != #{userId}

SELECT COUNT(1)
FROM room_member
WHERE room_id = #{roomId}

mapper.update:
UPDATE room_member
SET last_read_seq = #{lastReadSeq},
    update_time   = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND last_read_seq < #{lastReadSeq}

UPDATE room_member
SET hidden_at   = #{hiddenAt},
    update_time = NOW()
WHERE room_id = #{roomId}
  AND user_id = #{userId}

mapper.select:
SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.seq = #{seq}

SELECT 
FROM message m
WHERE m.room_id = #{roomId} AND m.client_msg_id = #{clientMsgId}

SELECT 
FROM message m
WHERE m.msg_id = #{messageId}

mapper.update:
UPDATE room_member
SET last_msg_preview = #{preview},
    update_time      = NOW()
WHERE room_id = #{roomId}
  AND (SELECT last_seq FROM room WHERE room_id = #{roomId}) = #{seq}

mapper.select:
SELECT 
FROM message m
WHERE m.room_id = #{roomId}

  AND m.seq < #{beforeSeq}

ORDER BY m.seq DESC
LIMIT #{limit}

SELECT t.msg_id AS msgId, t.delivery_seq AS deliverySeq
FROM timeline t
WHERE t.user_id = #{userId}
  AND t.delivery_seq > #{afterDeliverySeq}
ORDER BY t.delivery_seq ASC
LIMIT #{limit}

SELECT seq
FROM user_seq
WHERE user_id = #{userId}
